import { Effect } from "effect";
import { Headers, HttpClientRequest } from "effect/http";
import { Auth } from "../auth.js";
import { render as renderEndpoint } from "../endpoint.js";
import { Framing } from "../framing.js";
import * as ProviderShared from "../../protocols/shared.js";
import { mergeJsonRecords } from "../../schema/index.js";
import { RequestExecutor } from "../executor.js";
const bodyWithOverlay = (body, request, encodeBody) => Effect.gen(function* () {
    if (request.http?.body === undefined)
        return { jsonBody: body, bodyText: encodeBody(body) };
    if (ProviderShared.isRecord(body)) {
        const overlaid = mergeJsonRecords(body, request.http.body) ?? {};
        return { jsonBody: overlaid, bodyText: ProviderShared.encodeJson(overlaid) };
    }
    return yield* ProviderShared.invalidRequest("http.body can only overlay JSON object request bodies");
});
export const jsonRequestParts = (input) => Effect.gen(function* () {
    const endpoint = renderEndpoint(input.endpoint, { request: input.request, body: input.body });
    if (input.request.http?.query) {
        Object.entries(input.request.http.query).forEach(([key, value]) => endpoint.searchParams.set(key, value));
    }
    const url = endpoint.toString();
    const body = yield* bodyWithOverlay(input.body, input.request, input.encodeBody);
    const headers = yield* Auth.toEffect(input.auth)({
        request: input.request,
        method: "POST",
        url,
        body: body.bodyText,
        headers: Headers.fromInput({
            ...input.headers?.({ request: input.request }),
            ...input.request.headers,
        }),
    });
    return { url, jsonBody: body.jsonBody, bodyText: body.bodyText, headers };
});
export const httpJson = (input) => ({
    id: "http-json",
    with: (patch) => httpJson({ ...input, ...patch }),
    prepare: (prepareInput) => Effect.gen(function* () {
        const parts = yield* jsonRequestParts({ ...prepareInput });
        const request = ProviderShared.jsonPost({
            url: parts.url,
            body: parts.bodyText,
            headers: parts.headers,
            encoding: prepareInput.request.http?.encoding,
        });
        return {
            request,
            framing: input.framing,
            middleware: prepareInput.middleware,
        };
    }),
    execute: (prepared, request, runtime) => Effect.gen(function* () {
        const response = yield* RequestExecutor.withTimeout(RequestExecutor.withTls(runtime.http.execute, request.http?.tls), request.timeout)(prepared.request, prepared.middleware);
        return {
            frames: prepared.framing.frame(RequestExecutor.responseStream(response)),
            http: RequestExecutor.responseHttp(response),
            body: prepared.framing.body,
            raw: prepared.framing.raw,
        };
    }),
});
export const sseJson = {
    id: "http-json/sse",
    with: () => httpJson({ framing: Framing.sse }),
};
